"""Reference-led corporate composition; verified company content stays authoritative."""
def corporate_link(text,url):
 return f'<a class="corp-link" href="{url}">{text} <span aria-hidden="true">→</span></a>'

home_hero='''<section class="ref-hero corp-hero" aria-labelledby="home-title"><div class="ref-hero-photo"><video class="hero-video" autoplay muted loop playsinline preload="metadata" poster="assets/video/techno-industries-hero-poster.webp" aria-label="Techno Industries packaging manufacturing"><source src="assets/video/techno-industries-hero.mp4" type="video/mp4">Your browser does not support background video.</video><button class="hero-autoplay-toggle hero-video-toggle" type="button" aria-label="Pause manufacturing video" hidden>Ⅱ</button></div><div class="container ref-hero-content"><div><p class="corp-kicker">Your partner in corrugated packaging</p><h1 id="home-title">Quality packaging.<br>Made for your<br>business.</h1><p>Value-added corrugated boxes, printed packaging and custom solutions for local and international markets.</p><div class="button-row">'''+btn('Explore Our Products','products.html')+'''<a class="corp-hero-contact" href="contact.html">Talk to Our Team <span aria-hidden="true">→</span></a></div></div></div></section>'''

industry_home='<section class="corp-section corp-sectors" id="industries"><div class="container"><div class="corp-heading centered"><p class="eyebrow">INDUSTRIES WE SERVE</p><h2>Packaging for a wide range of industries</h2><p>From product presentation to protection in transit, we help businesses choose packaging for their application.</p></div><div class="corp-sector-list">'+''.join(f'<a href="industries.html#{slug}"><i data-lucide="{icon}" aria-hidden="true"></i><span>{name}</span><b aria-hidden="true">→</b></a>' for slug,icon,name,_,_ in industry_details)+'</div></div></section>'

about_home='<section class="corp-section corp-soft"><div class="container corp-about"><div class="corp-about-photo">'+img(1618,'Techno Industries team and corrugated packaging machinery')+'<div class="corp-photo-caption">Techno Industries · Raigama, Sri Lanka</div></div><div><p class="eyebrow">ABOUT TECHNO INDUSTRIES</p><h2>Practical expertise.<br>Value-added packaging.</h2><p>'+profile['overview']+'</p><h3>A focus on quality</h3><p>Our approach brings together technical expertise, food-grade certified materials and strict quality control, with continuous improvement at the heart of our work.</p>'+corporate_link('More About Our Company','about.html')+'</div></div><div class="container corp-about-links">'+''.join(f'<article><i data-lucide="{icon}" aria-hidden="true"></i><h3>{title}</h3><p>{desc}</p>'+corporate_link('Read More',url)+'</article>' for icon,title,desc,url in [('goal','Our Vision','Safe, durable and sustainable solutions that strengthen brands and protect products.','about.html#principles'),('factory','Our Capabilities','Corrugated board, flexographic and offset printing, die-cutting and surface finishing.','capabilities.html'),('shield-check','Our Quality Approach','ISO-certified manufacturing and food-grade materials for packaging requirements.','quality.html')])+'</div></section>'

solution_cards=[(1529,'Corrugated Packaging','Value-added corrugated boxes, standard boards and cartons for your product and distribution needs.','corrugated'),(1563,'Printed & Die-Cut Boxes','Print, shape and structure options to bring product protection and brand presentation together.','custom'),(1577,'Specialty Packaging','Handmade, recycled, gift, wooden and PVC boxes, alongside food-grade produce packaging.','all')]
solutions_home='<section class="corp-section"><div class="container"><div class="corp-heading with-action"><div><p class="eyebrow">OUR PACKAGING SOLUTIONS</p><h2>Find the right packaging for your product</h2><p>Explore the range, then discuss the board, dimensions, print and finish with our team.</p></div>'+corporate_link('View All Products','products.html')+'</div><div class="corp-solutions">'+''.join('<article><a class="corp-solution-photo" href="products.html#'+cat+'">'+img(n,title+' production at Techno Industries')+'</a><div><h3><a href="products.html#'+cat+'">'+title+'</a></h3><p>'+desc+'</p>'+corporate_link('Explore Range','products.html#'+cat)+'</div></article>' for n,title,desc,cat in solution_cards)+'</div></div></section>'

why_home='<section class="corp-section corp-soft"><div class="container"><div class="corp-heading centered"><p class="eyebrow">WHY CHOOSE TECHNO INDUSTRIES</p><h2>Built on the details that matter</h2><p>Materials, structure, print and finishing considered together for your packaging requirements.</p></div><div class="corp-reasons">'+''.join(f'<article><i data-lucide="{icon}" aria-hidden="true"></i><div><h3>{title}</h3><p>{desc}</p></div></article>' for icon,title,desc in [('layers','A choice of materials','F, E, B, C, BC and EB flutes, with single-, double- and triple-wall board options.'),('printer','Printing expertise','Flexographic printing in 1–4 colours, offset, line and multi-colour retail printing.'),('scan-line','Custom structures','Die-cut, self-locking, partitioned, telescopic and other box formats.'),('shield-check','Quality control','Strict quality control and continuous improvement guide our manufacturing approach.'),('leaf','Material considerations','Food-grade, recycled and moisture-resistant options for different applications.'),('package-check','Finishing options','OP varnish, UV and matte UV lamination, with structural enhancements.')])+'</div></div></section>'

process_home='<section class="corp-section"><div class="container corp-process-layout"><div><p class="eyebrow">START YOUR PACKAGING PROJECT</p><h2>Understanding your product comes first</h2><p>Tell us what you are packing, how it will be handled and the impression you want to make. These details help define a clear packaging brief.</p>'+corporate_link('Prepare a Packaging Enquiry','quotation.html')+'</div><ol class="corp-process">'+''.join(f'<li><span>0{i+1}</span><div><h3>{title}</h3><p>{desc}</p></div></li>' for i,(title,desc) in enumerate([('Share your requirements','Provide the product, quantity, dimensions and intended use.'),('Discuss materials and structure','Review the flute, board construction and box format for your application.'),('Define print and finishing','Share artwork, colours and any coating or structural requirements.'),('Confirm the specification','Agree the final requirements, relevant documentation and order details with our team.')]))+'</ol></div></section>'

marks_home='<section class="corp-marks corp-soft"><div class="container"><div><p class="eyebrow">QUALITY & INDUSTRY MARKS</p><h2>A commitment to quality</h2>'+corporate_link('Quality & Documentation','quality.html#certifications')+'</div><div class="corp-mark-images">'+''.join('<figure>'+profile_photo(name,title)+'<figcaption>'+('Organization logo' if name in ['edb-mark','cea-mark'] else title)+'</figcaption></figure>' for name,title,_ in profile_marks)+'</div></div></section>'
contact_home='<section class="corp-contact-banner"><div class="corp-banner-photo">'+img(1554,'Manufacturing floor at Techno Industries')+'</div><div class="container"><p class="eyebrow">LET’S DISCUSS YOUR REQUIREMENTS</p><h2>Techno Industries</h2><p>Value-added corrugated packaging. Part of Techno Group.</p><div class="corp-banner-contacts"><a href="mailto:info@technoind.biz"><span>Email Us</span>info@technoind.biz</a><a href="tel:+94382257170"><span>Call Our Team</span>+94 38 225 7170</a>'+btn('Request a Quote','quotation.html')+'</div></div></section>'
title,desc,_=pages['index']
pages['index']=(title,desc,home_hero+industry_home+about_home+solutions_home+why_home+process_home+marks_home+contact_home)

# Owner identity supplied by the user. Company commitments remain corporate copy,
# rather than an invented personal quotation, title, biography or signature.
owner_section='''<section class="corp-section corp-leadership" id="leadership" aria-labelledby="leadership-title"><div class="container corp-leadership-layout"><figure class="corp-owner-photo"><img src="assets/media/owner-portrait-1600.webp" srcset="assets/media/owner-portrait-640.webp 640w, assets/media/owner-portrait-1600.webp 1600w" sizes="(max-width: 800px) 100vw, 52vw" width="1600" height="1067" alt="Owner of Techno Industries" loading="lazy" decoding="async"><figcaption><strong>Owner</strong><span>Techno Industries</span></figcaption></figure><div class="corp-leadership-copy"><p class="eyebrow">OUR LEADERSHIP</p><h2 id="leadership-title">Leadership at <br>Techno Industries</h2><p>Quality, innovation and customer service are central to our approach to packaging.</p><p>Our commitments to continuous improvement, sustainability and strict quality control support the durability, structural integrity and presentation of our packaging.</p><div class="corp-leadership-focus"><h3>Our company focus</h3><ul>'''+''.join('<li>'+html.escape(value)+'</li>' for value in profile['focus'])+'''</ul></div>'''+corporate_link('Explore Our Quality Approach','quality.html')+'''</div></div></section>'''
title,desc,body=pages['about']
body=body.replace('<section class="about-approach">',owner_section+'<section class="about-approach">',1)
pages['about']=(title,desc,body)

# Write for customers; source provenance is maintained in the content audit.
copy_refinements={
 'Purpose-built packaging for the sectors named in our company profile.':'Packaging solutions for tea, apparel, food, industrial and other business applications.',
 'Our company profile brings together ten product lines, supported by a range of board constructions, flute profiles and structural formats.':'Explore ten product lines with a choice of board constructions, flute profiles and structural formats.',
 'From shipping cartons to display formats, the company profile lists these structures.':'From shipping cartons to display formats, choose a structure suited to your product.',
 'Flute profiles listed in the company profile for print, cushioning and structural requirements.':'Explore flute profiles for print, cushioning and structural requirements.',
 'PVC packaging is listed as a new product line in the company profile. Applications include retail, gifts, cosmetics and confectionery.':'Our PVC packaging range includes options for retail, gifts, cosmetics and confectionery.',
 'Recycled box options listed in the company product range.':'Recycled box options for your packaging requirements.'
}
for key,(title,desc,body) in list(pages.items()):
 for old,new in copy_refinements.items():body=body.replace(old,new)
 pages[key]=(title,desc,body)

